  1→/* W24 console prompt panel: the real-browser contract, written RED-first by the planner's
  2→ * RED-test preparer. Driven by tests/test_w24_prompt_panel.py (RealBrowserPromptPanel), which
  3→ * starts the real server on an ephemeral port with real mock runs and passes:
  4→ *   argv: <base url> <report json path>
  5→ *   env:  PUPPETEER_MODULE, BROWSER_EXECUTABLE, W24_EXPECT (run ids, stored fingerprints, strings)
  6→ * It never files, decides or writes; the only interference is holding or failing the
  7→ * /prompts requests it names, each released explicitly.
  8→ */
  9→const assert = require('node:assert/strict');
 10→const fs = require('node:fs');
 11→const puppeteer = require(process.env.PUPPETEER_MODULE || 'puppeteer');
 12→const [base, output] = process.argv.slice(2);
 13→const X = JSON.parse(process.env.W24_EXPECT);
 14→const report = {passed: false, cases: [], errors: []};
 15→const frames = page => page.evaluate(() => new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r))));
 16→const badge = fp => 'Matches what was sent (fingerprint ' + fp.slice(0, 8) + ')';
 17→
 18→async function panel(page) {
 19→  return page.evaluate(() => {
 20→    const root = document.getElementById('prompts-content');
 21→    if (!root) return null;
 22→    return {
 23→      text: root.textContent,
 24→      articles: Array.from(root.querySelectorAll('article')).map(a => ({
 25→        heading: (a.querySelector('h1,h2,h3,h4,h5,h6') || {}).textContent || null,
 26→        text: a.textContent,
 27→        details: a.querySelectorAll('details').length,
 28→        summary: (a.querySelector('details > summary') || {}).textContent || null,
 29→        pre: (a.querySelector('details pre') || {}).textContent || null,
 30→        dl: a.querySelectorAll('dl').length,
 31→      })),
 32→    };
 33→  });
 34→}
 35→
 36→(async () => {
 37→  const browser = await puppeteer.launch({headless: true, executablePath: process.env.BROWSER_EXECUTABLE,
 38→    args: ['--no-sandbox']});
 39→  try {
 40→    // 1. Deep link to a ruled run, desktop then narrow: three articles, exact badges, order.
 41→    for (const [width, height] of [[1280, 900], [390, 844]]) {
 42→      const page = await browser.newPage();
 43→      page.on('pageerror', e => report.errors.push(String(e)));
 44→      await page.setViewport({width, height});
 45→      await page.goto(base + '/?run=' + encodeURIComponent(X.ruled), {waitUntil: 'domcontentloaded'});
 46→      await page.waitForFunction(() => document.querySelectorAll('#prompts-content article').length === 3,
 47→        {timeout: 10000});
 48→      const p = await panel(page);
 49→      assert.deepEqual(p.articles.map(a => a.heading), X.labels);
 50→      p.articles.forEach((a, i) => {
 51→        assert.ok(a.text.includes(badge(X.fingerprints.ruled[i])), 'badge for ' + X.labels[i]);
 52→        assert.ok(a.dl >= 1, 'summary is a <dl>');
 53→        assert.equal(a.details, 1);
 54→        assert.equal(a.summary, X.summary);
 55→      });
 56→      assert.ok(p.articles[0].pre.startsWith('You are the Rider Advocate'), 'full text starts with the system prompt');
 57→      assert.ok(p.articles[0].pre.includes('\n\nDISPUTE\n'), 'system and user prompt joined by a blank line');
 58→      const order = await page.evaluate(() => Array.from(document.querySelectorAll('#case-workspace > section'))
 59→        .map(s => s.id));
 60→      assert.deepEqual(order.slice(2, 5), ['evidence-section', 'prompts-section', 'claims-section']);
 61→      // Open every full text and require no horizontal page overflow (narrow viewport included).
 62→      await page.evaluate(() => document.querySelectorAll('#prompts-content details').forEach(d => { d.open = true; }));
 63→      await frames(page);
 64→      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
 65→      assert.ok(overflow <= 1, 'open full text overflows the page by ' + overflow + 'px at ' + width);
 66→      // Each full text stays inside its card: it wraps, or it scrolls inside itself.
 67→      const pres = await page.evaluate(() => Array.from(document.querySelectorAll('#prompts-content article')).map(a => {
 68→        const pre = a.querySelector('details pre');
 69→        const s = getComputedStyle(pre);
 70→        return {inside: pre.getBoundingClientRect().right <= a.getBoundingClientRect().right + 1,
 71→          fits: pre.scrollWidth <= pre.clientWidth + 1, scrolls: ['auto', 'scroll'].includes(s.overflowX)};
 72→      }));
 73→      pres.forEach((p, i) => {
 74→        assert.ok(p.inside, X.labels[i] + ' full text runs outside its card at ' + width);
 75→        assert.ok(p.fits || p.scrolls, X.labels[i] + ' full text is cut off at ' + width);
 76→      });
 77→      report.cases.push({deepLink: X.ruled, width, overflow, pres});
 78→      await page.close();
 79→    }
 80→
 81→    // 2. Stale responses: open case A from the queue, hold its /prompts, open case B, then release
 82→    //    A as a late success and as a late failure. B's panel must survive both.
 83→    for (const stale of ['success', 'failure']) {
 84→      const page = await browser.newPage();
 85→      page.on('pageerror', e => report.errors.push(String(e)));
 86→      await page.setViewport({width: 1280, height: 900});
 87→      await page.setRequestInterception(true);
 88→      const held = [];
 89→      page.on('request', r => (r.url().endsWith('/api/review/' + encodeURIComponent(X.a) + '/prompts')
 90→        ? held.push(r) : r.continue()));
 91→      await page.goto(base + '/', {waitUntil: 'domcontentloaded'});
 92→      const open = id => page.click('.queue-row[data-run-id="' + id + '"] .queue-open');
 93→      await page.waitForSelector('.queue-row[data-run-id="' + X.a + '"] .queue-open');
 94→      await page.waitForSelector('.queue-row[data-run-id="' + X.b + '"] .queue-open');
 95→      await open(X.a);
 96→      const start = Date.now();
 97→      while (!held.length) { assert.ok(Date.now() - start < 5000, 'A prompts not requested'); await new Promise(r => setTimeout(r, 10)); }
 98→      await open(X.b);
 99→      await page.waitForFunction(fp => document.getElementById('prompts-content').textContent.includes(fp),
100→        {timeout: 10000}, badge(X.fingerprints.withheld[0]));
101→      const before = await panel(page);
102→      if (stale === 'success') await held[0].continue();
103→      else await held[0].respond({status: 500, contentType: 'application/json', body: '{"error":"late"}'});
104→      await new Promise(r => setTimeout(r, 300));
105→      await frames(page);
106→      const after = await panel(page);
107→      assert.deepEqual(after, before, 'a late ' + stale + ' for case A changed case B\'s panel');
108→      assert.ok(!after.text.includes(badge(X.fingerprints.filed[0])), 'case A badge rendered');
109→      assert.ok(!after.text.includes(X.badgeFailure), 'case A failure rendered');
110→      report.cases.push({stale, articles: after.articles.length});
111→      await page.close();
112→    }
113→
114→    // 3. An invalid deep link says so and renders nothing.
115→    {
116→      const page = await browser.newPage();
117→      page.on('pageerror', e => report.errors.push(String(e)));
118→      await page.goto(base + '/?run=..%2Fetc', {waitUntil: 'load'});
119→      await new Promise(r => setTimeout(r, 300));
120→      await frames(page);
121→      assert.equal(await page.$eval('#load-status', e => e.textContent), X.unknown);
122→      assert.equal(await page.$eval('#case-workspace', e => e.hidden), true);
123→      report.cases.push({invalidDeepLink: true});
124→      await page.close();
125→    }
126→
127→    // 4. The server is gone for the prompts request: the one fixed sentence.
128→    {
129→      const page = await browser.newPage();
130→      page.on('pageerror', e => report.errors.push(String(e)));
131→      await page.setRequestInterception(true);
132→      page.on('request', r => (r.url().endsWith('/prompts') ? r.abort('connectionrefused') : r.continue()));
133→      await page.goto(base + '/?run=' + encodeURIComponent(X.ruled), {waitUntil: 'domcontentloaded'});
134→      await page.waitForFunction(() => document.getElementById('case-workspace').hidden === false
135→        && document.getElementById('prompts-content').textContent.length > 0, {timeout: 10000});
136→      await new Promise(r => setTimeout(r, 200));
137→      assert.equal(await page.$eval('#prompts-content', e => e.textContent), X.badgeFailure);
138→      report.cases.push({serverGone: true});
139→      await page.close();
140→    }
141→
142→    assert.deepEqual(report.errors, []);
143→    report.passed = true;
144→  } catch (e) {
145→    report.error = String(e && e.stack || e);
146→    process.exitCode = 1;
147→  } finally {
148→    await browser.close();
149→    fs.writeFileSync(output, JSON.stringify(report, null, 2));
150→    console.log(JSON.stringify({passed: report.passed, cases: report.cases.length, error: report.error}));
151→  }
152→})().catch(e => { console.error(e); process.exitCode = 1; });
